{
  "units": [
    {
      "issue": "U0：截至2023-08-01的三笔债务清算范围及保证人即时给付责任",
      "decisive_facts": [
        "情景明确为虚构；结算截至2023-08-01，不计当日利息，不存在未列明付款或其他法律例外。",
        "甲请求乙返还A剩余实际交付财产、支付B全部可保护本息、支付C未偿本金、合法利息及未偿费用。",
        "甲同时要求丁、戊、己立即支付，但不请求保证合同无效后的过错赔偿。",
        "各输出分项最终取分后再汇总，不作不同债务交叉冲抵。"
      ],
      "support_spans": [
        {
          "source": "material_pack.normalized_text",
          "spans": ["导言（未分配span_id）", "S12"]
        }
      ],
      "dependencies": {
        "requires": ["U1", "U2", "U3", "U4", "U5", "U6", "U7"],
        "edges": [
          {
            "from": "U3、U4、U6的债务分项",
            "to": "乙的债务总额",
            "relation": "分别确定项目与数额，最终取分后相加。"
          },
          {
            "from": "U3、U5、U7的保证状态",
            "to": "丁、戊、己即时给付请求的支持范围",
            "relation": "保证责任须分别判断，不因主债务存在而自动成立。"
          },
          {
            "from": "同一主债务及其保证责任",
            "to": "汇总口径",
            "relation": "保证责任不是新增主债务，不能重复累计。"
          }
        ]
      },
      "answerability": {
        "status": "supported_for_p1",
        "scope": "材料足以提取主问题及依赖图；精确金额留待后续定点计算与独立复算。",
        "caution": "四种保证状态是分类选项，不意味着本题必须各出现一种。当前事实不支持己属于期间内有效保全的状态。"
      }
    },
    {
      "issue": "U1：适用规范版本与旧版无效要件的排除",
      "decisive_facts": [
        "三笔借款均发生于2022年，案件于2023-08-01新受理。",
        "A存在套取银行信贷资金转贷事实，同时乙事先不知资金来源、约定利率仅6%。",
        "提供的规范包括2015年、2020年8月和2020年12月三个民间借贷司法解释版本。"
      ],
      "support_spans": [
        {
          "source": "material_pack.normalized_text",
          "spans": ["导言（未分配span_id）", "S01", "S03", "S07"]
        },
        {
          "source_id": "lending-2020-12",
          "provisions": ["13", "31"],
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html"
        },
        {
          "source_id": "civil-code-2020",
          "provisions": ["1260"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
        },
        {
          "source_id": "lending-2015",
          "provisions": ["14"],
          "role": "历史版本对照，不作为本情景的适用依据"
        }
      ],
      "dependencies": {
        "requires": [],
        "edges": [
          {
            "from": "借款发生时间及案件受理时间",
            "to": "适用2021-01-01起施行的所附规范",
            "relation": "不进入2020-08-20以前成立合同的过渡分支。"
          },
          {
            "from": "适用的第十三条第一项",
            "to": "A无效要件",
            "relation": "不附加2015年版本中的高利转贷及借款人知情要求。"
          }
        ]
      },
      "answerability": {
        "status": "supported",
        "supported_state": "就题设时点，采用所附2020年12月修正版本及民法典；乙不知情和6%利率不排除A触及贷款转贷无效条款。"
      }
    },
    {
      "issue": "U2：实际交付、实际付款与重复凭证的交易级归并",
      "decisive_facts": [
        "A的票面、收据和到账记录指向同一次交付。",
        "B预扣利息未交付乙，各次结息借据没有新增现金交付。",
        "T-01主表、截图和手写收据具有同一银行交易号。",
        "X-01失败未结算，银行及双方确认没有实际到账。",
        "T-01至T-04均已结算，乙分别指定偿还C。"
      ],
      "support_spans": [
        {
          "source": "material_pack.normalized_text",
          "spans": ["S02", "S03", "S04", "S05", "S08", "S11"]
        },
        {
          "source_id": "civil-code-2020",
          "provisions": ["560", "670", "679"]
        },
        {
          "source_id": "lending-2020-12",
          "provisions": ["26", "27"]
        }
      ],
      "dependencies": {
        "requires": [],
        "edges": [
          {
            "from": "交易号、结算状态及双方确认",
            "to": "唯一实际交易集合",
            "relation": "重复凭证不增加交易；失败指令不构成付款。"
          },
          {
            "from": "债务指定",
            "to": "付款归属",
            "relation": "T-01至T-04归入C，不转用于清偿A或B。"
          },
          {
            "from": "现金交付与结息凭证的区分",
            "to": "A返还基数及B初始本金、后期本金",
            "relation": "无新增交付不等于合法结息一律不能计入后期本金。"
          }
        ]
      },
      "answerability": {
        "status": "supported",
        "supported_state": "实际交易集合可由题设唯一确定；无需推断未披露付款或新增借款。"
      }
    },
    {
      "issue": "U3：A的合同效力、返还财产范围及丁的保证合同效力",
      "decisive_facts": [
        "A资金来源为甲套取的银行信贷资金，来源已由题设证实。",
        "A票面160000元，实际交付142885.00元。",
        "乙此前返还19985.00元；双方仅在A被认定无效的条件下约定全部冲抵应返还财产。",
        "甲不请求未交付票面差额、其他无效后赔偿或抵扣。",
        "丁虽约定连带保证，但题设不存在独立于主合同无效的法定例外。"
      ],
      "support_spans": [
        {
          "source": "material_pack.normalized_text",
          "spans": ["S01", "S02", "S11", "S12"]
        },
        {
          "source_id": "lending-2020-12",
          "provisions": ["13"]
        },
        {
          "source_id": "civil-code-2020",
          "provisions": ["157", "682"]
        }
      ],
      "dependencies": {
        "requires": ["U1", "U2"],
        "edges": [
          {
            "from": "贷款转贷事实与适用无效条款",
            "to": "A合同无效",
            "relation": "合同效力由事实与规范判断，不由附条件清算协议预设。"
          },
          {
            "from": "A无效、实际交付及附条件冲抵协议",
            "to": "A剩余返还财产",
            "relation": "以实际交付减已返还财产，不以票面本金或约定利息清算。"
          },
          {
            "from": "A主合同无效且无例外",
            "to": "丁保证合同无效",
            "relation": "不能将未请求的过错赔偿替代为连带保证债务。"
          }
        ]
      },
      "answerability": {
        "status": "supported",
        "supported_states": [
          "A合同无效。",
          "A返还分项以142885.00元减19985.00元确定。",
          "丁的保证合同无效，本题不建立其连带保证给付金额。"
        ]
      }
    },
    {
      "issue": "U4：B的实际本金、合法结息及双层利率限制",
      "decisive_facts": [
        "B于2022-01-12实际到账181850.00元，当日成立并起息；票面193995.00元包含预扣利息12145.00元。",
        "约定年利率13.200%，合同成立时一年期LPR题设值为3.70%。",
        "2022-07-06和2023-01-09分别出具结息借据，纸面本金为206272.49元和220222.16元。",
        "新借据没有新增现金、债务更新或新增独立费用，沿用原利率及最初合同成立时LPR。",
        "B从未另行还款，展期后于2023-06-30到期，甲请求截至截日的全部可保护本息。",
        "按实际自然日、年基数365计算，中间不取分。"
      ],
      "support_spans": [
        {
          "source": "material_pack.normalized_text",
          "spans": ["S03", "S04", "S05", "S06", "S11", "S12"]
        },
        {
          "source_id": "civil-code-2020",
          "provisions": ["670", "679", "680"]
        },
        {
          "source_id": "lending-2020-12",
          "provisions": ["25", "26", "27", "28"]
        }
      ],
      "dependencies": {
        "requires": ["U1", "U2"],
        "edges": [
          {
            "from": "实际到账及预扣事实",
            "to": "初始本金181850.00元",
            "relation": "预扣部分不能作为初始本金计息。"
          },
          {
            "from": "初始本金、约定利率、结息日期及结息约定",
            "to": "各期可计入后期本金的合法利息",
            "relation": "审查纸面金额的真实构成，不能直接沿用名义本金。"
          },
          {
            "from": "约定利率13.200%与LPR四倍14.80%",
            "to": "逐期利息保护范围",
            "relation": "保护上限不是可直接替换约定利率的计息利率。"
          },
          {
            "from": "合法结息结果与最初本金",
            "to": "整期本息上限审查",
            "relation": "逐期利率合规仍须另行适用第二十七条第二款总额限制。"
          },
          {
            "from": "展期后到期日、最终请求及第二十八条",
            "to": "到期后至截日的利息范围",
            "relation": "逾期部分须有独立规范依据，不能因借据换写而另起本金或更换LPR。"
          }
        ]
      },
      "answerability": {
        "status": "supported_for_calculation",
        "supported_state": "本金、计息起点、结息节点、利率及限额依据齐全，可建立确定性清算。",
        "pending": "尚未执行逐段金额计算及整期上限比较，不预填最终金额或认定哪一上限实际触发。"
      }
    },
    {
      "issue": "U5：B未经保证人同意展期后的保证期间及戊的连带责任",
      "decisive_facts": [
        "戊书面约定连带责任保证，未约定保证期间。",
        "B原到期日为2023-01-12，后展期至2023-06-30；戊未书面同意展期。",
        "甲首次要求戊承担保证责任并到达戊的日期为2023-07-05。",
        "戊已书面同意合法结息机制，保证范围涵盖原B关系依法清算的全部本息及合法结息部分。"
      ],
      "support_spans": [
        {
          "source": "material_pack.normalized_text",
          "spans": ["S06", "S12"]
        },
        {
          "source_id": "civil-code-2020",
          "provisions": ["688", "691", "692", "693", "695"]
        }
      ],
      "dependencies": {
        "requires": ["U1", "U4"],
        "edges": [
          {
            "from": "未约定保证期间且未书面同意展期",
            "to": "以原到期日计算六个月保证期间",
            "relation": "展期不改变对戊适用的保证期间。"
          },
          {
            "from": "2023-07-05到达的责任请求",
            "to": "期间内向连带保证人行权",
            "relation": "该请求早于按原到期日计算的2023-07-12届满日。"
          },
          {
            "from": "期间内行权、主债务已到期及约定范围",
            "to": "戊的即时连带给付范围",
            "relation": "金额依赖U4的可保护本息，不采用未经审查的纸面本金。"
          }
        ]
      },
      "answerability": {
        "status": "supported",
        "supported_state": "戊不因保证期间届满免责；截至截日，可在约定保证范围内请求其承担连带责任。"
      }
    },
    {
      "issue": "U6：C指定债务后的内部清偿顺序及分时余额",
      "decisive_facts": [
        "C于2022-02-07实际交付222050.00元，无预扣；借期内及逾期年利率均为11.40%，题设LPR为3.70%。",
        "依法可收取的实现债权费用1680元，在所有付款前已到期。",
        "T-01至T-04的日期和金额分别为2022-04-18的9865.00元、2022-08-23的11596.00元、2022-11-14的13327.00元、2023-02-21的15058.00元。",
        "仅T-02存在双方书面约定：先本金、再费用、最后利息。",
        "其余付款没有另行顺序约定；单方附言不构成双方协议。",
        "按未清本金、实际自然日/365单利累计，不对未付利息计息；付款当日不再对已偿还本金计息。"
      ],
      "support_spans": [
        {
          "source": "material_pack.normalized_text",
          "spans": ["S07", "S08", "S09", "S11", "S12"]
        },
        {
          "source_id": "civil-code-2020",
          "provisions": ["560", "561", "679", "680"]
        },
        {
          "source_id": "lending-2020-12",
          "provisions": ["25", "28"]
        }
      ],
      "dependencies": {
        "requires": ["U1", "U2"],
        "edges": [
          {
            "from": "乙对C的债务指定",
            "to": "四笔有效付款归入C",
            "relation": "债务选择不等于该债务内部一律先还本金。"
          },
          {
            "from": "T-02双方约定及其他付款无约定",
            "to": "各笔付款适用的清偿顺序",
            "relation": "T-02适用约定例外；其余适用费用、利息、主债务的顺序。"
          },
          {
            "from": "付款前应计利息、未偿费用及当笔顺序",
            "to": "付款后的本金、利息和费用余额",
            "relation": "各类余额分别更新，不机械从本金扣除全部付款。"
          },
          {
            "from": "更新后的本金及保留的未付利息",
            "to": "下一期间应计利息及最终分项",
            "relation": "本金减少影响后续计息，保留利息不产生复利。"
          }
        ]
      },
      "answerability": {
        "status": "supported_for_calculation",
        "supported_state": "有效付款、顺序例外、计息规则与截日齐全，可确定未偿本金、利息和费用。",
        "pending": "最终金额须逐段定点计算并复核；本阶段不输出未经复算的金额标签。"
      }
    },
    {
      "issue": "U7：C保证方式、保证期间行权要求及己的责任状态",
      "decisive_facts": [
        "己的保证合同未约定保证方式和保证期间。",
        "C主债务于2022-12-15到期。",
        "甲于2023-05-08向己发送要求支付的短信。",
        "甲直到2023-06-20才对乙提起独立诉讼；题设明确以该日作为相应行权日期。",
        "截至截日前诉未审判，乙有可执行财产，无第687条例外，己未放弃先诉抗辩。"
      ],
      "support_spans": [
        {
          "source": "material_pack.normalized_text",
          "spans": ["S07", "S10", "S12"]
        },
        {
          "source_id": "civil-code-2020",
          "provisions": ["686", "687", "692", "693"]
        }
      ],
      "dependencies": {
        "requires": ["U1"],
        "edges": [
          {
            "from": "未约定保证方式",
            "to": "一般保证",
            "relation": "不能按连带责任保证的行权方式判断。"
          },
          {
            "from": "2022-12-15到期且未约定保证期间",
            "to": "六个月保证期间于2023-06-15届满",
            "relation": "不能以催告短信中断、延长保证期间。"
          },
          {
            "from": "短信对象为己、对乙起诉日期为2023-06-20",
            "to": "未在保证期间内完成一般保证所要求的行权",
            "relation": "向保证人催告不能替代对债务人起诉或申请仲裁；实际起诉已晚于期间届满。"
          },
          {
            "from": "未按期行权",
            "to": "己不再承担保证责任",
            "relation": "本题最终状态不是仅因先诉抗辩而暂不能立即给付。"
          }
        ]
      },
      "answerability": {
        "status": "supported",
        "supported_state": "己属于保证期间届满且未依法行权而不再承担保证责任的状态。",
        "caution": "题设所称在2023-06-20行使保证权利，只确定行为日期，不能解释为已在保证期间内有效保全。"
      }
    }
  ],
  "rejected_units": [
    {
      "issue": "将己认定为期间内有效保全、仅尚有先诉抗辩",
      "reason": "对乙起诉发生于2023-06-20，晚于2023-06-15保证期间届满；此前向己发送短信不满足一般保证的法定行权要求。",
      "support_spans": [
        "S07",
        "S10",
        "civil-code-2020:686",
        "civil-code-2020:692",
        "civil-code-2020:693"
      ],
      "disposition": "拒绝作为正向状态标签；保留U7所载受支持状态，不在P1修改题设日期。"
    },
    {
      "issue": "提取法院已经确认的三笔债务金额或保证责任裁判结论",
      "reason": "材料明确为虚构衍生情景，没有可提取的真实法院认定、裁判理由或裁判结果。",
      "support_spans": [
        "material_pack.source.kind",
        "material_pack.source.not_original_case_evidence",
        "material_pack.normalized_text#导言"
      ],
      "disposition": "仅建立题设事实与所附规范支持的状态及计算依赖，不赋予真实裁判标签。"
    },
    {
      "issue": "丁因保证合同无效应承担的精确过错赔偿",
      "reason": "题设排除该项请求，亦未提供用于分配具体过错责任的充分事实；不能将其并入连带保证债务。",
      "support_spans": [
        "S12",
        "civil-code-2020:682"
      ],
      "disposition": "排除在本轮主问题及金额依赖图之外。"
    }
  ],
  "limitations": [
    {
      "type": "事实来源边界",
      "detail": "全部案件事实均为显著虚构题设。双方认可资料真实性属于情景设定，不是外部证据核验结果。"
    },
    {
      "type": "规范核验边界",
      "detail": "本次仅引用所提供的官方链接及摘录；未实际访问网页、核验下载哈希或独立确认版本元数据，不宣称已完成外部规范核验。"
    },
    {
      "type": "计算边界",
      "detail": "P1仅登记可计算性和必要依赖，未执行逐段定点计算、最终取分及独立复算，不产生已核验的精确金额参考。"
    },
    {
      "type": "机制覆盖",
      "detail": "当前事实支持丁保证合同无效、戊可被请求连带支付、己因未按期行权而免责。材料机制标签不能替代日期与法定行权方式，期间内保全但尚有先诉抗辩的分支未获得本题事实支持。"
    },
